i would like to possess a DIV list on which the user can traverse by pressing up/down cursor keys and receiving event when he modifies the current DIV, as it occurs in Google Instant results. Do you know if there is a jQuery/JS component to realize it or any recommendations on the components to utilize.

Thanks !

Edit

I altered it to use mouseover for emphasizing the divs and setting the content of the input on click and the arrow keys. I believe this is more akin to Google's which is what you desired.

End Edit

I just composed this for you. I hope you're capable of using it: http://jsfiddle.net/Paulpro/evBkC/8/ It should be simple to adjust the css to style it the manner you want from there. It emphasizes a div onclick and detects the up and down arrow keys if the input field has focus. It retains track of the selectedDiv's index in a variable called selectedDiv so you can use it if you wish. It should be entirely cross-browser as far back as IE 5.5 at the least and all the other major browsers.

HTML:

Line 1  
Line 2  
Line 3  
Line 4  
Line 5  
Line 6  

CSS:

#nav, #nav input{  
  width: 300px;   
}

#nav div{  
  width: 150px;     
  margin-left: 75px;  
  border-right: 1px solid #000;  
  border-bottom: 1px solid #000;  
  border-left: 1px solid #000;  
  cursor: pointer;  
}

Javascript:

var divs = document.getElementById('nav').getElementsByTagName('div'),  
selectedDiv = 0,  
i;  

for(i = 0; i < divs.length; i++){  
    divs[i].onmouseover = (function(i){  
       return function(){  
           divs[selectedDiv].style.backgroundColor = '';  
           selectedDiv = i;  
           divs[selectedDiv].style.backgroundColor = '#68F';  
       }  
    })(i);  

    divs[i].onclick = function(){  
        document.getElementById('nav').  
          getElementsByTagName('input')[0].focus();  
        document.getElementById('nav').  
          getElementsByTagName('input')[0].value =  
            (this.innerText || this.textContent);  
    };  
}  

divs[selectedDiv].style.backgroundColor = '#68F';  

document.getElementById('nav').  
  getElementsByTagName('input')[0].onkeydown = function(e){  
     var x = 0;  
     if(e.keyCode == 38)  
         x = -1;  
     else if(e.keyCode == 40)  
         x = 1;  
     else  
         return;  
     divs[selectedDiv].style.backgroundColor = '';  
     selectedDiv = ((selectedDiv+x)%divs.length);  
     selectedDiv = selectedDiv < 0 ?  
       divs.length+selectedDiv : selectedDiv;  
     document.getElementById('nav').  
       getElementsByTagName('input')[0].value =  
         (divs[selectedDiv].innerText || divs[selectedDiv].textContent);  
     divs[selectedDiv].style.backgroundColor = '#68F';  
};  

document.getElementById('nav').  
  getElementsByTagName('input')[0].focus();

